CREATE TABLE orders (
  order_id     NUMBER PRIMARY KEY,
  customer     VARCHAR2(50),
  status       VARCHAR2(20),
  amount       NUMBER(10,2)
);

INSERT INTO orders VALUES (101, 'Asha',  'NEW',     2500);
INSERT INTO orders VALUES (102, 'Ravi',  'NEW',     1800);
INSERT INTO orders VALUES (103, 'Meena', 'SHIPPED', 4200);
COMMIT;

-- Session 1: updates order 101 and does NOT commit
UPDATE orders SET status = 'PAID' WHERE order_id = 101;

-- Session 2: tries to update the same row. It hangs.
UPDATE orders SET amount = 2600 WHERE order_id = 101;

-- Session 3: also wants order 101. It hangs too.
DELETE FROM orders WHERE order_id = 101;

